const vineDrape = (x0, z0, x1, z1, h = 4.5, c) => { const M0 = mk().M, pts = [], n = 9; for (let k = 0; k <= n; k++) { const t = k / n; pts.push(new THREE.Vector3(x0 + (x1 - x0) * t, h - Math.sin(Math.PI * t) * 1.3, z0 + (z1 - z0) * t)); } add(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 20, 0.03, 4), M0.leaf); for (let k = 1; k < n; k++) { const L = 0.2 + R() * 0.6; add(new THREE.CylinderGeometry(0.008, 0.008, L, 3), M0.rope, [pts[k].x, pts[k].y - L / 2, pts[k].z]); add(new THREE.SphereGeometry(0.07, 8, 6), MK.glowC(c || ["#3ff0ff", "#c8ff6a", "#ff7ad8", "#ffd27a"][k % 4], 2), [pts[k].x, pts[k].y - L, pts[k].z]); } };
