const feeder = (x, z, c = "#ffb347") => { const M0 = mk().M, G = grp(x, 0, z, R() * TAU); add(new THREE.CylinderGeometry(0.06, 0.08, 1.1, 6), M0.bark, [0, 0.55, 0], [0, 0, 0], null, G); add(olathe([[0.001, 0], [0.4, 0.02], [0.45, 0.14], [0.001, 0.1]], 16), M0.plank, [0, 1.1, 0], [0, 0, 0], null, G); for (let k = 0; k < 6; k++) add(new THREE.SphereGeometry(0.06, 8, 6), MK.glowC(c, 1.4), [(R() - 0.5) * 0.5, 1.22, (R() - 0.5) * 0.5], [0, 0, 0], null, G); };
const berryBush = (x, z, c = "#ff5ad8") => { const b = add(BUSHG(), mk().M.leaf || mk().M.moss, [x, 0.45, z], [R(), R(), R()]); b.scale.set(0.75, 0.55, 0.75); for (let k = 0; k < 10; k++) { const a = R() * TAU, e = R() * 1.2; add(new THREE.SphereGeometry(0.05, 6, 5), MK.glowC(c, 1.3), [x + Math.cos(a) * Math.cos(e) * 0.7, 0.45 + Math.sin(e) * 0.5, z + Math.sin(a) * Math.cos(e) * 0.7]); } };
const wildSign = (x, z, ry = 0, c = "#c8f06a") => { const G = grp(x, 0, z, ry), M0 = mk().M; add(new THREE.CylinderGeometry(0.06, 0.07, 1.4, 6), M0.bark, [0, 0.7, 0], [0, 0, 0], null, G); const b = add(warp(new THREE.BoxGeometry(0.8, 0.5, 0.06, 2, 2, 1), 0.02, 2), M0.plank, [0, 1.3, 0], [0, 0, 0], null, G); const t = tex(128, 80, (g, W, Hh) => { g.fillStyle = "#6a4a2a"; g.fillRect(0, 0, W, Hh); g.strokeStyle = c; g.lineWidth = 6; g.beginPath(); for (let k = 0; k < 5; k++) { const xx = 22 + k * 21; g.moveTo(xx, 66); g.quadraticCurveTo(xx + 8, 40, xx + 2 + (k % 2) * 8, 14); } g.stroke(); g.fillStyle = c; g.beginPath(); g.arc(98, 22, 9, 0, TAU); g.fill(); }); add(new THREE.PlaneGeometry(0.72, 0.42), std({ map: t, emissive: c, emissiveIntensity: 0.25 }), [0, 1.3, 0.035], [0, 0, 0], null, G); };
// ================= PLACES: pocket scenes, dungeon floors and special interiors (Part 2 pack, sections 6 and 7) =================
// Each place is its own small world far from the region (x >= 400), built on a tile grid of its own.
// Tiles: '#' wall, ' ' void (a drop), '.' floor, ',' stone floor, 'g' glowgrass, 'b' bridge, 'v' violet safe-path moss,
//        'w' water, 'o' solid obstacle, 'S' stairs / hatch / doorway (walkable).
const PLACE = {}; const PLW = (w, d, c = "#") => Array.from({ length: d }, () => Array(w).fill(c));
const pRect = (g, x0, y0, x1, y1, c = ".") => { for (let y = Math.max(0, y0); y <= Math.min(g.length - 1, y1); y++) for (let x = Math.max(0, x0); x <= Math.min(g[0].length - 1, x1); x++) g[y][x] = c; };
const pCirc = (g, cx, cy, r, c = ".", ry = r) => { for (let y = 0; y < g.length; y++) for (let x = 0; x < g[0].length; x++) if (((x + 0.5 - cx) / r) ** 2 + ((y + 0.5 - cy) / ry) ** 2 < 1) g[y][x] = c; };
const pPath = (g, pts, w = 4, c = ".") => { for (let k = 0; k + 1 < pts.length; k++) { const [x0, y0] = pts[k], [x1, y1] = pts[k + 1], n = Math.ceil(Math.hypot(x1 - x0, y1 - y0) * 2); for (let i = 0; i <= n; i++) { const x = x0 + ((x1 - x0) * i) / n, y = y0 + ((y1 - y0) * i) / n; pCirc(g, x, y, w / 2, c); } } };
// wobble the carved edges so caves never look like rooms
const pRough = (g, amt = 0.35, seed = 1) => { const H = g.length, W = g[0].length, o = g.map((r) => r.slice()); for (let y = 1; y < H - 1; y++) for (let x = 1; x < W - 1; x++) { if (o[y][x] !== "#") continue; let n = 0; for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (o[y + dy][x + dx] === ".") n++; if (n >= 2 && fbm(x * 0.4 + seed, y * 0.4, seed) > 0.5 - amt) g[y][x] = "."; } };
const PX0 = 400, PZ0 = 400; let PK = 0;
const defPlace = (id, o) => { o.id = id; o.ox = PX0 + PK * 80; o.oz = PZ0; PK++; PLACE[id] = o; };

// ---------- the twelve places ----------
defPlace("canopy", { name: "Canopy Walkways", w: 30, d: 30, style: "canopy", indoor: false, grid() { const g = PLW(30, 30, " "); const C = [[15, 24, 4.3], [7, 16, 3.8], [15, 15, 4.2], [23, 16, 3.8], [8, 6, 3.6], [22, 6, 4.0]]; this.caps = C; for (const [x, y, r] of C) pCirc(g, x, y, r, "."); for (const [a, b] of [[0, 2], [1, 2], [2, 3], [1, 4], [3, 5], [2, 5]]) { const [x0, y0] = C[a], [x1, y1] = C[b]; pPath(g, [[x0, y0], [x1, y1]], 3, "b"); } for (const [x, y, r] of C) pCirc(g, x, y, r, "."); pCirc(g, 7, 16, 2.4, "g"); pCirc(g, 23, 16, 2.2, "g"); pRect(g, 14, 28, 15, 28, "S"); pRect(g, 14, 27, 15, 27, "."); return g; },
  arrive: { in: [15, 26.5, 0] }, portals: [{ t: [15, 28.5], to: "out:A5", label: "Climb down the Spiral Stalk" }] });
