const vineOn = (G, h) => { for (let k = 0; k < 3; k++) { const a = R() * TAU; limb([[Math.cos(a) * 0.47, 0, Math.sin(a) * 0.47], [Math.cos(a + 0.6) * 0.5, h * 0.4, Math.sin(a + 0.6) * 0.5], [Math.cos(a + 1.2) * 0.48, h * 0.75, Math.sin(a + 1.2) * 0.48]], 0.03, 0.02, mk().M.moss, { seg: 10, rad: 4, knob: 0, parent: G }); } };
const yDrum = (x, z, ry = R() * TAU) => { const d = add(warp(new THREE.CylinderGeometry(0.44, 0.44, 1.0, 14), 0.03, 2), yStoneM(), [x, 0.4, z], [Math.PI / 2, ry, 0]); return d; };
const yBlock = (x, z, s = 1) => add(soft(new THREE.BoxGeometry(1.1 * s, 0.7 * s, 0.8 * s, 2, 1, 2), { warp: 0.06 }), yStoneM(), [x, 0.3 * s, z], [R() * 0.2, R() * TAU, R() * 0.15]);
