const yTablet = (x, z, ry = 0, h = 2.2) => { const G = grp(x, 0, z, ry); add(soft(new THREE.BoxGeometry(1.4, h, 0.35, 2, 3, 1), { warp: 0.04 }), yStoneM(), [0, h / 2, 0], [0, 0, 0], null, G); const t = tex(128, 192, (g, W, Hh) => { g.clearRect(0, 0, W, Hh); g.strokeStyle = "#bff8ff"; g.lineWidth = 3; for (let r = 12; r < 50; r += 12) { g.beginPath(); g.arc(W / 2, 70, r, 0, TAU); g.stroke(); } for (let k = 0; k < 8; k++) { const a = (k / 8) * TAU; g.beginPath(); g.moveTo(W / 2, 70); g.lineTo(W / 2 + Math.cos(a) * 58, 70 + Math.sin(a) * 58); g.stroke(); } for (let k = 0; k < 5; k++) { g.beginPath(); g.arc(20 + k * 22, 150, 6, 0, TAU); g.stroke(); } }); add(new THREE.PlaneGeometry(1.2, 1.8), std({ map: t, transparent: true, emissive: YC.glyph, emissiveMap: t, emissiveIntensity: 1.4, depthWrite: false }), [0, h * 0.55, 0.18], [0, 0, 0], null, G).name = "nocol"; return G; };

