const fBush = (x, z, s, c, y = 0.1) => { const b = add(BUSHG(), FM(c, { roughness: 0.95 }), [x, y, z], [R(), R(), R()]); b.scale.set(s * (0.8 + R() * 0.5), s * (0.45 + R() * 0.35), s * (0.8 + R() * 0.5)); return b; };
// open a passage between an old scene and a new one: carve tiles after its ground is laid, clear props from the corridor after it is built
