  MK.weaveT = tex(512, 512, (g, W) => { g.fillStyle = "#c8b48a"; g.fillRect(0, 0, W, W); const n = 16, s = W / n; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) { const over = (i + j) % 2; const gr = over ? g.createLinearGradient(i * s, 0, i * s + s, 0) : g.createLinearGradient(0, j * s, 0, j * s + s); gr.addColorStop(0, "rgba(90,70,40,0.55)"); gr.addColorStop(0.5, "rgba(255,245,220,0.25)"); gr.addColorStop(1, "rgba(60,45,25,0.6)"); g.fillStyle = gr; g.fillRect(i * s + 1, j * s + 1, s - 2, s - 2); }
    for (let k = 0; k < 800; k++) { g.strokeStyle = `rgba(${R() < 0.5 ? "70,50,25" : "255,240,210"},${0.08 + R() * 0.12})`; g.lineWidth = 1; const x = R() * W, y = R() * W; g.beginPath(); g.moveTo(x, y); g.lineTo(x + (R() - 0.5) * 12, y + (R() - 0.5) * 12); g.stroke(); } hp(g, W, W, false, 0.6); }, [3, 2]);
