const edgeGrove = (x0, y0, x1, y1, lowSouth = false) => { if (lowSouth) { const n = Math.round((x1 - x0 + 1) * (y1 - y0 + 1) * 0.6); for (let k = 0; k < n; k++) giantMush(x0 + R() * (x1 - x0 + 1), y0 + R() * (y1 - y0 + 1), 0.8 + R() * 1.1, 0.4 + R() * 0.45, ["#3fe0d0", "#b06ad8", "#ffb347", "#7a3fa0"][k % 4]); for (let k = 0; k < n; k++) { const b = add(BUSHG(), R() < 0.5 ? mk().M.moss : mk().M.moss2, [x0 + R() * (x1 - x0 + 1), 0.1, y0 + R() * (y1 - y0 + 1)], [R(), R(), R()]); b.scale.set(0.5 + R() * 0.5, 0.3, 0.5 + R() * 0.5); } } else stalkWall(x0, y0, x1, y1); };
