    { const A = add(olathe([[0.001, 0.2], [0.7, 0.24], [0.9, 0.4], [1.0, 0.36], [1.05, 0], [0.001, 0]], 24, 0.02, 2), D.adobe("#f0e0c8"), [cx, 0.07, cz - rz * 0.76]); A.scale.z = 0.6; const gl = add(new THREE.CircleGeometry(0.8, 24), MK.glowC("#7ff0e6", 0.9), [cx, 0.42, cz - rz * 0.76], [-Math.PI / 2, 0, 0]); gl.scale.y = 0.6; ilight(cx, 1.2, cz - rz * 0.72, "#7ff0e6", 2.6, 6); } // the healing alcove
