    { const S = grp(X(16), 0, Z(2.6)); for (let k = 0; k < 6; k++) add(new THREE.BoxGeometry(3, 0.3, 0.6), D.sandstone(), [0, 0.15 + k * 0.3, -k * 0.5 + 1], [0, 0, 0], null, S).name = "nocol"; } // stairs up
