    // the Bloom Bed: a ring of rare cacti whose flowers glow faintly pink, at the north-east dead end (Cactling)
    { const bx = X + 27.0, bz = Y + 5.4; for (let k = 0; k < 8; k++) { const a = (k / 8) * TAU; const b = add(D.geo().barrel, D.cactus(), [bx + Math.cos(a) * 1.0, 0, bz + Math.sin(a) * 1.0]); b.scale.set(1.6, 2.0, 1.6); add(D.geo().bloom, MK.glowC("#ff7ab8", 1.6), [bx + Math.cos(a) * 1.0, 0.65, bz + Math.sin(a) * 1.0]).scale.setScalar(1.8); } const l = new THREE.PointLight(0xff7ab8, 2, 5, 1.6); l.position.set(bx, 1.2, bz); root.add(l); }
    dSlab(X + 1.6, Y + 25.2, 0.2); dSlab(X + 27.4, Y + 6.4, 0.4); // the two dead-end stash slabs
