// ================= DUSTARA EXPANSION: 8 more scenes on the open edges of the canyon wilds (owner request: more wild areas and lived-in stops) =================
// None of these are in the pack. They join the pack's scenes through new 6-wide side paths, so the pack's own route and crossings are unchanged.
// New links (global tiles): DC6|DC7 x=180 y 72-77 · DC7|DC8 x=210 y 72-77 · DC7/DD7 y=90 x 201-206 · DC8/DD8 y=90 x 222-227 · DD7|DD8 x=210 y 102-107 (plank bridge)
//   DD8/DE8 y=120 x 222-227 · DE7|DE8 x=210 y 132-137 · DE6/DF6 y=150 x 162-167 · DF6|DF7 x=180 y 162-167 · DE7/DF7 y=150 x 199-204 · DF5/DG5 y=180 x 132-137
//   DD3|DD4 x=90 y 104-109 · DD3/DE3 y=120 x 72-77
const XG = (X, Y) => dGround(X, Y);
// carve the side paths into the pack scenes they join (runs after each scene's own ground)
const XLINK = { DC6: (F) => F(24, 12, 29, 17, "p"), DD7: (F) => { F(25, 12, 29, 17, "k"); F(21, 0, 26, 2, "k"); }, DE7: (F) => { F(27, 12, 29, 17, "p"); F(19, 24, 24, 29, "p"); }, DF5: (F) => F(12, 24, 17, 29, "p"), DE6: (F) => F(12, 24, 17, 29, "p"), DD4: (F) => F(0, 14, 7, 19, "p"), DE3: (F) => F(12, 0, 17, 2, "p") };
const XLINKB = { DD7: (X, Y) => { boardwalk(X + 25, Y + 12, X + 29.6, Y + 17); boardwalk(X + 21, Y + 0, X + 26, Y + 2.6); } };
for (const id of Object.keys(XLINK)) { const s = SCN[id], g0 = s.ground, b0 = s.build; s.ground = function () { g0.call(this); XLINK[id](XG(...s.rect)); }; if (XLINKB[id]) s.build = function () { b0.call(this); XLINKB[id](...s.rect); }; }
const xWell = (x, z) => { add(olathe([[0.9, 0], [0.9, 0.8], [0.75, 0.85], [0.75, 0.15], [0.001, 0.15]], 20, 0.02, 2), D.sandstone(), [x, 0, z]); add(new THREE.CircleGeometry(0.75, 20), std({ color: "#2aa8b0", emissive: "#0a4a50", emissiveIntensity: 0.5 }), [x, 0.6, z], [-Math.PI / 2, 0, 0]).name = "water"; for (const s of [-0.8, 0.8]) add(new THREE.CylinderGeometry(0.06, 0.06, 1.9, 6), D.wood(), [x + s, 0.95, z]); add(new THREE.BoxGeometry(2.0, 0.5, 1.2), D.roofM ? D.roofM() : D.turq(), [x, 2.0, z], [0, 0, 0]); };
