  m018: ["lo_blinkit", "lo_bogeel", "lo_cactling", "lo_drippit", "lo_dunetrot", "lo_skitterdrone", "lo_spinelord"], m019: ["lo_bogeel", "lo_cactling", "lo_chirpod", "lo_drippit", "lo_dunetrot", "lo_grayvision", "lo_spinelord"],
